from ta_moler.device.nokia_unix_remote import NokiaUnixRemote
from moler.helpers import call_base_class_method_with_same_name, mark_to_call_base_class_method_with_same_name


@call_base_class_method_with_same_name
class AsiMgr(NokiaUnixRemote):
    r"""
    AsiMgr device class.

    Example of device in yaml configuration file:
    - with PROXY_PC:
      ASIMGR:
       DEVICE_CLASS: ta_moler.device.asi_mgr.AsiMgr
       CONNECTION_HOPS:
         UNIX_LOCAL:
           PROXY_PC:
             execute_command: ssh # default value
             command_params:
               expected_prompt: proxy_pc_prompt
               host: host_ip
               login: login
               password: password
         PROXY_PC:
           UNIX_REMOTE:
             execute_command: ssh # default value
             command_params:
               expected_prompt: 'ute@[\w-]+:(?!(/opt/asir\$\s+))' # default value
               host: host_ip
               login: login
               password: password
         UNIX_REMOTE:
           CLI:
             execute_command: cd # default value
             command_params:
               path:  /opt/asir/ # default value
               expected_prompt: 'ute@[\w-]+:/opt/asir\$\s+' # default value
           PROXY_PC:
             command_params:
               expected_prompt: proxy_pc_prompt
         CLI:
           UNIX_REMOTE:
             execute_command: cd # default value
             command_params:
               path:  '~' # default value
               expected_prompt: 'ute@[\w-]+:(?!(/opt/asir\$\s+))' # default value
    - without PROXY_PC:
      ASIMGR:
       DEVICE_CLASS: ta_moler.device.asi_mgr.AsiMgr
       CONNECTION_HOPS:
         UNIX_LOCAL:
           UNIX_REMOTE:
             execute_command: ssh # default value
             command_params:
               expected_prompt: 'ute@[\w-]+:(?!(/opt/asir\$\s+))' # default value
               host: host_ip
               login: login
               password: password
         UNIX_REMOTE:
           CLI:
             execute_command: cd # default value
             command_params:
               path:  /opt/asir/ # default value
               expected_prompt: 'ute@[\w-]+:/opt/asir\$\s+' # default value
         CLI:
           UNIX_REMOTE:
             execute_command: cd # default value
             command_params:
               path:  '~' # default value
               expected_prompt: 'ute@[\w-]+:(?!(/opt/asir\$\s+))' # default value
    """

    cli = "CLI"

    def __init__(self, sm_params, name=None, io_connection=None, io_type=None, variant=None, io_constructor_kwargs=None,
                 initial_state=None, lazy_cmds_events=False):
        """
        Create AsiMgr device communicating over io_connection.

        :param sm_params: dict with parameters of state machine for device
        :param name: name of device
        :param io_connection: External-IO connection having embedded moler-connection
        :param io_type: type of connection - tcp, udp, ssh, telnet, ...
        :param variant: connection implementation variant, ex. 'threaded', 'twisted', 'asyncio', ...
                        (if not given then default one is taken)
        :param io_constructor_kwargs: additional parameter into constructor of selected connection type
                        (if not given then default one is taken)
        :param initial_state: name of initial state. State machine tries to enter this state just after creation.
        :param lazy_cmds_events: set False to load all commands and events when device is initialized, set True to load
                        commands and events when they are required for the first time.
        """
        initial_state = initial_state if initial_state is not None else AsiMgr.cli
        super(AsiMgr, self).__init__(name=name, io_connection=io_connection,
                                     io_type=io_type, variant=variant,
                                     io_constructor_kwargs=io_constructor_kwargs,
                                     sm_params=sm_params, initial_state=initial_state,
                                     lazy_cmds_events=lazy_cmds_events)

    @mark_to_call_base_class_method_with_same_name
    def _get_default_sm_configuration_with_proxy_pc(self):
        """
        Return State Machine default configuration with proxy_pc state.

        :return: default sm configuration with proxy_pc state.
        """
        config = {
            AsiMgr.connection_hops: {
                AsiMgr.proxy_pc: {  # from
                    AsiMgr.unix_remote: {  # to
                        "execute_command": "ssh",  # using command
                        "command_params": {  # with parameters
                            "target_newline": "\n",
                            "expected_prompt": r"ute@[\w-]+:(?!(/opt/asir\$\s+))",
                        },
                        "required_command_params": [
                            "host",
                            "login",
                            "password",
                        ]
                    },
                },
                AsiMgr.unix_remote: {  # from
                    AsiMgr.cli: {  # to
                        "execute_command": "cd",  # using command
                        "command_params": {  # with parameters
                            "path": "/opt/asir/",
                            "expected_prompt": r"ute@[\w-]+:/opt/asir\$\s+",
                        },
                        "required_command_params": [
                        ]
                    }
                },
                AsiMgr.cli: {
                    AsiMgr.unix_remote: {
                        "execute_command": "cd",  # using command
                        "command_params": {  # with parameters
                            "path": "~",
                            "expected_prompt": r"ute@[\w-]+:(?!(/opt/asir\$\s+))",
                        },
                        "required_command_params": [
                        ]
                    }
                }
            }
        }
        return config

    def _prepare_asi_mgr_transitions(self):
        transitions = {
            AsiMgr.cli: {
                AsiMgr.unix_remote: {
                    "action": [
                        "_execute_command_to_change_state"
                    ],
                }
            },
            AsiMgr.unix_remote: {
                AsiMgr.cli: {
                    "action": [
                        "_execute_command_to_change_state"
                    ],
                },
            }
        }
        return transitions

    @mark_to_call_base_class_method_with_same_name
    def _prepare_transitions_with_proxy_pc(self):
        """
        Prepare transitions to change states with proxy_pc state.

        :return: transitions with proxy_pc state.
        """
        return self._prepare_asi_mgr_transitions()

    def _prepare_asi_mgr_state_prompts(self):
        state_prompts = {
            AsiMgr.cli:
                self._configurations[AsiMgr.connection_hops][AsiMgr.unix_remote][AsiMgr.cli][
                    "command_params"]["expected_prompt"],
            AsiMgr.unix_remote:
                self._configurations[AsiMgr.connection_hops][AsiMgr.cli][AsiMgr.unix_remote][
                    "command_params"]["expected_prompt"],
        }
        return state_prompts

    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_prompts_with_proxy_pc(self):
        """
        Prepare textual prompt for each state for State Machine with proxy_pc state.

        :return: textual prompt for each state with proxy_pc state.
        """
        return self._prepare_asi_mgr_state_prompts()

    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_prompts_without_proxy_pc(self):
        """
        Prepare textual prompt for each state for State Machine without proxy_pc state.

        :return: textual prompt for each state without proxy_pc state.
        """
        return self._prepare_asi_mgr_state_prompts()

    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_hops_with_proxy_pc(self):
        """
        Prepare non direct transitions for each state for State Machine with proxy_pc state.

        :return: non direct transitions for each state with proxy_pc state.
        """
        state_hops = {
            AsiMgr.not_connected: {
                AsiMgr.cli: AsiMgr.unix_local
            },
            AsiMgr.unix_local: {
                AsiMgr.cli: AsiMgr.proxy_pc
            },
            AsiMgr.proxy_pc: {
                AsiMgr.cli: AsiMgr.unix_remote
            },
            AsiMgr.cli: {
                AsiMgr.proxy_pc: AsiMgr.unix_remote,
                AsiMgr.unix_local: AsiMgr.unix_remote,
                AsiMgr.unix_local_root: AsiMgr.unix_remote,
                AsiMgr.unix_remote_root: AsiMgr.unix_remote,
                AsiMgr.not_connected: AsiMgr.unix_remote
            },
            AsiMgr.unix_remote_root: {
                AsiMgr.cli: AsiMgr.unix_remote
            },
            AsiMgr.unix_local_root: {
                AsiMgr.cli: AsiMgr.unix_local
            }
        }
        return state_hops

    def _get_packages_for_state(self, state, observer):
        """
        Get available packages contain cmds and events for each state.

        :param state: device state.
        :param observer: observer type, available: cmd, events
        :return: available cmds or events for specific device state.
        """
        available = super(AsiMgr, self)._get_packages_for_state(state, observer)

        if not available:
            if state == AsiMgr.cli:
                available = {AsiMgr.cmds: ['moler.cmd.unix', 'ta_moler.cmd.shared.nokiaunix', 'ta_moler.cmd.asimgr'],
                             AsiMgr.events: ['moler.events.shared', 'moler.events.unix']}
                return available[observer]

        return available
